local function C_10()
	local script = LMG2L["LocalScript_10"];
	local button = script.Parent

	local player = game.Players.LocalPlayer

	local playerGui = player:WaitForChild("PlayerGui")



	-- Crear la pantalla del jumpscare

	local gui = Instance.new("ScreenGui")

	gui.ResetOnSpawn = false

	gui.Enabled = false

	gui.Parent = playerGui



	local imagen = Instance.new("ImageLabel")

	imagen.Size = UDim2.new(0, 1920, 0, 1010)

	imagen.BackgroundTransparency = 1

	imagen.Image = "rbxassetid://104735490829332"

	imagen.Parent = gui



	local sonido = Instance.new("Sound")

	sonido.SoundId = "rbxassetid://74464434454195"

	sonido.Volume = 1

	sonido.Parent = gui



	button.MouseButton1Click:Connect(function()

		gui.Enabled = true

		sonido:Play()



		task.wait(8) -- El jumpscare dura 8 segundos



		gui.Enabled = false

		sonido:Stop()

	end)	
end;
task.spawn(C_10);
